-- The Desk, sign-off and viewers (ARCHITECTURE v0.12 §5.5, §11.1, §4). `inbox_item` gains
-- `deliver_after` (approved inside the undo window: the run is told after it), `batch_key`
-- (`<run id>:<step id>`, the items one step proposed together) and a snooze (`snoozed_until`,
-- `snoozed_by`). `external_action` gains the signer's edit (`edited_input`, `edited_by`,
-- `edited_at`); `input` stays the agent's version. `membership.can_sign` (default true; false: a
-- viewer). Nullable columns and a column with a default only, so the previous Worker keeps working:
-- it never writes them, it delivers at once as before (deliver_after null), executes `input`
-- (edited_input null) and lets everyone sign as before (can_sign true). Generated by drizzle-kit;
-- the existing grants (UPDATE on all three) and row-level security already cover the new columns.
ALTER TABLE "external_action" ADD COLUMN "edited_input" jsonb;--> statement-breakpoint
ALTER TABLE "external_action" ADD COLUMN "edited_by" uuid;--> statement-breakpoint
ALTER TABLE "external_action" ADD COLUMN "edited_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "inbox_item" ADD COLUMN "deliver_after" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "inbox_item" ADD COLUMN "batch_key" text;--> statement-breakpoint
ALTER TABLE "inbox_item" ADD COLUMN "snoozed_until" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "inbox_item" ADD COLUMN "snoozed_by" uuid;--> statement-breakpoint
ALTER TABLE "membership" ADD COLUMN "can_sign" boolean DEFAULT true NOT NULL;--> statement-breakpoint
ALTER TABLE "external_action" ADD CONSTRAINT "external_action_edited_by_app_user_id_fk" FOREIGN KEY ("edited_by") REFERENCES "public"."app_user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "inbox_item" ADD CONSTRAINT "inbox_item_snoozed_by_app_user_id_fk" FOREIGN KEY ("snoozed_by") REFERENCES "public"."app_user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "inbox_item_batch_idx" ON "inbox_item" USING btree ("tenant_id","batch_key") WHERE "inbox_item"."batch_key" is not null;--> statement-breakpoint
ALTER TABLE "external_action" ADD CONSTRAINT "external_action_edit_check" CHECK (("external_action"."edited_input" is null) = ("external_action"."edited_at" is null));
